const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={cars:[],locations:[]},view='cars',editing=null,dirty=false,uploading=false,busy=false,photo={},gallery=[];
const money=value=>value==null?'On request':'₹'+value.toLocaleString('en-IN')+' / day';
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers:{...(options.body&&typeof options.body==='string'?{'Content-Type':'application/json'}:{}),...options.headers}});let data;try{data=await response.json();}catch{throw Error('Could not reach GoRide. Please try again.');}if(!response.ok){if(response.status===401)throw Error('Your owner session has expired. Sign out and sign in with your GoRide owner account.');throw Error(data.error||'Could not save. Please try again.');}return data;}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000);}
function render(){if(window.customerAdmin?.active){window.customerAdmin.render();return;}const term=$('fleet-search').value.trim().toLowerCase();$('stat-cars').textContent=state.cars.length;const enabled=new Set(state.locations.filter(l=>l.enabled).map(l=>l.id));$('stat-active').textContent=state.cars.filter(c=>c.status==='active'&&c.locationIds.some(id=>enabled.has(id))).length;$('stat-locations').textContent=enabled.size;$('page-title').innerHTML=view==='cars'?'Your fleet<span>.</span>':'Your locations<span>.</span>';$('page-subtitle').textContent=view==='cars'?'Manage cars, photos, daily rates and where you offer them.':'Add cities and pick-up areas, or pause a location.';$('add-button').textContent=view==='cars'?'+ Add car':'+ Add location';$('fleet-search').placeholder=view==='cars'?'Search by car name':'Search by location';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));
if(view==='cars'){const cars=state.cars.filter(c=>c.name.toLowerCase().includes(term));$('owner-content').innerHTML=cars.length?'<div class="owner-grid">'+cars.map(c=>`<article class="owner-card"><div class="owner-image">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:''}<span class="owner-status ${esc(c.status)}">${c.status==='active'?'Visible':c.status==='maintenance'?'Maintenance':'Hidden'}</span></div><div class="owner-details"><h3>${esc(c.name)}</h3><p class="owner-meta">${esc(c.category)} · ${c.seats} seats<br>${esc(c.locationIds.map(id=>state.locations.find(l=>l.id===id)?.name||'Unknown location').join(' · '))}</p><div class="owner-rates"><div><span>SELF-DRIVE</span><strong>${c.selfEnabled?money(c.selfRate):'Not offered'}</strong></div><div><span>WITH A CHAUFFEUR</span><strong>${c.driverEnabled?money(c.driverRate):'Not offered'}</strong></div></div><div class="owner-actions"><small>${c.deposit==null?'Deposit on request':'Deposit ₹'+c.deposit.toLocaleString('en-IN')}</small><button class="secondary" data-edit-car="${esc(c.id)}">Edit car</button></div></div></article>`).join('')+'</div>':'<div class="admin-empty">'+(term?'No cars match your search.':'Your next car belongs here. Use Add car to start.')+'</div>';}else{const locations=state.locations.filter(l=>l.name.toLowerCase().includes(term));$('owner-content').innerHTML=locations.length?'<div class="location-list">'+locations.map(l=>`<article class="location-item ${l.enabled?'':'location-inactive'}"><span class="kicker">${l.enabled?'ACTIVE LOCATION':'PAUSED LOCATION'}</span><h3>${esc(l.name)}</h3><p>${state.cars.filter(c=>c.locationIds.includes(l.id)).length} assigned cars${l.enabled?'':' · Hidden from customer searches'}</p><button class="secondary" data-edit-location="${esc(l.id)}">Edit location</button></article>`).join('')+'</div>':'<div class="admin-empty">No locations match your search.</div>';}}
async function load(initialize=false){$('admin-error').textContent='';$('refresh').disabled=true;try{const session=await api('/api/admin/session');$('owner-email').textContent=session.email;state=await api(initialize?'/api/admin/initialize':'/api/admin/catalog',initialize?{method:'POST'}:{});$('add-button').disabled=false;render();return true;}catch(e){$('admin-error').textContent=e.message;$('add-button').disabled=true;$('owner-content').innerHTML='<div class="admin-empty">Your catalogue could not be loaded. Use Refresh to try again.</div>';return false;}finally{$('refresh').disabled=false;}}
function field(label,id,value='',type='text',extra=''){return `<label class="field"><span>${esc(label)}</span><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function openCar(id){if(!state.locations.length){toast('Add a location before adding a car.');return;}const car=id?state.cars.find(c=>c.id===id):{name:'',category:'Hatchback',seats:5,status:'active',selfEnabled:true,driverEnabled:true,selfRate:null,driverRate:null,deposit:null,locationIds:state.locations.filter(l=>l.enabled).map(l=>l.id),image:'',imageCredit:'',imageSource:'',imageLicense:'',notes:''};editing={kind:'car',...car};gallery=(car.gallery||[]).map(p=>({...p}));photo={image:car.image,imageCredit:car.imageCredit,imageSource:car.imageSource,imageLicense:car.imageLicense};$('edit-title').textContent=id?'Edit car':'Add a car';$('save-button').textContent='Save car';$('edit-fields').innerHTML=`<div class="field-grid">${field('Car name','name',car.name,'text','required maxlength="100"') }<label class="field"><span>Category</span><select id="category">${['Hatchback','Sedan','SUV','MPV','Luxury'].map(c=>`<option ${car.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('Seats','seats',car.seats,'number','required min="2" max="20" step="1"')}<label class="field"><span>Listing status</span><select id="status">${[['active','Visible to customers'],['hidden','Hidden'],['maintenance','Under maintenance']].map(([v,label])=>`<option value="${v}" ${car.status===v?'selected':''}>${label}</option>`).join('')}</select></label><div class="field full"><span>Rental types</span><div class="check-list"><label><input id="self-enabled" type="checkbox" ${car.selfEnabled?'checked':''}>Self-drive</label><label><input id="driver-enabled" type="checkbox" ${car.driverEnabled?'checked':''}>With a chauffeur</label></div></div>${field('Self-drive rate · ₹ per day','self-rate',car.selfRate??'','number','min="0" max="10000000" step="1"')}${field('Chauffeur rate · ₹ per day','driver-rate',car.driverRate??'','number','min="0" max="10000000" step="1"')}${field('Security deposit · ₹','deposit',car.deposit??'','number','min="0" max="10000000" step="1"')}<div class="field"><span>Prices on request?</span><small>Leave a price blank to show “Request a quote”. Rates are daily base prices; add inclusions or limits in the notes below.</small></div><div class="field full"><span>Available locations</span><div class="check-list">${state.locations.map(l=>`<label><input type="checkbox" name="location" value="${esc(l.id)}" ${car.locationIds.includes(l.id)?'checked':''}>${esc(l.name)}${l.enabled?'':' (paused)'}</label>`).join('')}</div></div><div class="field full"><span>Car photo</span><div class="photo-editor"><img id="photo-preview" ${car.image?`src="${esc(car.image)}"`:''} alt="Car photo preview"><div><input type="file" id="photo-file" accept="image/jpeg,image/png,image/webp" aria-label="Upload car photo"><small id="upload-status">JPG, PNG or WebP · maximum 8 MB. Upload your own car photo. It is attached when you save the car.</small></div></div><details><summary class="url-toggle">Use an image link or manage photo credits</summary><div class="field-grid">${field('HTTPS image link','photo-url',car.image,'text','maxlength="2000"')}${field('Photo credit (optional)','photo-credit',car.imageCredit,'text','maxlength="200"')}${field('Source page (optional)','photo-source',car.imageSource,'text','maxlength="2000"')}${field('Photo license (optional)','photo-license',car.imageLicense,'text','maxlength="60"')}</div></details></div><div class="field full"><span>More car photos · up to 7</span><input type="file" id="gallery-upload" accept="image/jpeg,image/png,image/webp" multiple aria-label="Add car slideshow photos"><small id="gallery-status">Upload photos of this car. Customers can swipe between them.</small><div class="gallery-editor" id="gallery-editor"></div></div><label class="field full"><span>Rental notes (visible to customers)</span><textarea id="notes" maxlength="1000" placeholder="For example: 250 km per day; fuel excluded; extra kilometres charged separately.">${esc(car.notes)}</textarea></label></div>`;renderGallery();$('gallery-upload').addEventListener('change',uploadGallery);$('photo-file').addEventListener('change',uploadPhoto);$('photo-url').addEventListener('change',()=>{const value=$('photo-url').value.trim();if(value!==photo.image){photo={image:value,imageCredit:'',imageSource:'',imageLicense:''};$('photo-credit').value='';$('photo-source').value='';$('photo-license').value='';}if(value.startsWith('https://')||value.startsWith('/media/'))$('photo-preview').src=value;});showEditor();}
async function uploadPhoto(){const file=$('photo-file').files[0];if(!file)return;dirty=true;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){$('form-error').textContent='Choose a JPG, PNG or WebP photo smaller than 8 MB.';return;}uploading=true;$('save-button').disabled=true;$('form-error').textContent='';$('upload-status').textContent='Uploading photo…';try{const result=await api('/api/admin/photos',{method:'POST',headers:{'Content-Type':file.type},body:file});photo={image:result.url,imageCredit:'',imageSource:'',imageLicense:''};$('photo-preview').src=result.url;$('photo-url').value=result.url;for(const id of ['photo-credit','photo-source','photo-license'])$(id).value='';$('upload-status').textContent='Photo uploaded. Save the car to show it to customers.';}catch(e){$('form-error').textContent=e.message;$('upload-status').textContent='Photo was not uploaded. Please try again.';}finally{uploading=false;$('save-button').disabled=false;}}
function openLocation(id){const l=id?state.locations.find(x=>x.id===id):{name:'',enabled:true};editing={kind:'location',...l};$('edit-title').textContent=id?'Edit location':'Add a location';$('save-button').textContent='Save location';$('edit-fields').innerHTML=`<div class="field-grid"><div class="field full">${field('City or pick-up area','location-name',l.name,'text','required maxlength="80"')}</div><div class="field full"><div class="check-list"><label><input id="location-enabled" type="checkbox" ${l.enabled?'checked':''}>Active location</label></div><small>Pausing hides this location and its assigned cars from searches in that location. Cars assigned to other active locations stay visible.</small></div></div>`;if(!id)$('location-enabled').disabled=true;showEditor();}
function showEditor(){dirty=false;busy=false;$('form-error').textContent='';$('save-button').disabled=false;$('edit-dialog').showModal();}
function closeEditor(){if(uploading||busy){toast('Please wait until the current upload or save finishes.');return;}if(dirty&&!confirm('Discard your unsaved changes?'))return;$('edit-dialog').close();editing=null;dirty=false;}
$('edit-form').addEventListener('input',()=>{dirty=true;});$('edit-form').addEventListener('submit',async event=>{event.preventDefault();if(uploading||busy)return;busy=true;$('save-button').disabled=true;$('form-error').textContent='';try{let path,method=editing.id?'PUT':'POST',data;if(editing.kind==='car'){const amount=id=>$(id).value.trim()===''?null:Number($(id).value);data={...editing,name:$('name').value,category:$('category').value,seats:Number($('seats').value),status:$('status').value,selfEnabled:$('self-enabled').checked,driverEnabled:$('driver-enabled').checked,selfRate:amount('self-rate'),driverRate:amount('driver-rate'),deposit:amount('deposit'),locationIds:[...document.querySelectorAll('input[name="location"]:checked')].map(x=>x.value),image:$('photo-url').value.trim(),imageCredit:$('photo-credit').value,imageSource:$('photo-source').value,imageLicense:$('photo-license').value,gallery:readGallery(),notes:$('notes').value};path='/api/admin/cars'+(editing.id?'/'+editing.id:'');}else{data={...editing,name:$('location-name').value,enabled:$('location-enabled').checked};path='/api/admin/locations'+(editing.id?'/'+editing.id:'');}const saved=await api(path,{method,body:JSON.stringify(data)});const key=editing.kind==='car'?'cars':'locations';const index=state[key].findIndex(x=>x.id===saved.id);if(index<0)state[key].unshift(saved);else state[key][index]=saved;dirty=false;$('edit-dialog').close();render();toast(editing.kind==='car'?'Car saved. Your customer catalogue is updated.':'Location saved. Your customer catalogue is updated.');editing=null;}catch(e){$('form-error').textContent=e.message;}finally{busy=false;$('save-button').disabled=false;}});
$('close-editor').onclick=closeEditor;$('cancel-editor').onclick=closeEditor;$('edit-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});$('add-button').onclick=()=>view==='cars'?openCar():openLocation();$('refresh').onclick=refreshDashboard;$('fleet-search').addEventListener('input',render);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(window.customerAdmin)window.customerAdmin.active=false;$('add-button').hidden=false;view=b.dataset.view;$('fleet-search').value='';render();});$('owner-content').addEventListener('click',e=>{const car=e.target.closest('[data-edit-car]'),location=e.target.closest('[data-edit-location]');if(car)openCar(car.dataset.editCar);if(location)openLocation(location.dataset.editLocation);});load(true);

function readGallery(){return [...document.querySelectorAll('.gallery-editor-row')].map(row=>({url:row.querySelector('[data-photo-field="url"]').value.trim(),credit:row.querySelector('[data-photo-field="credit"]').value.trim(),source:row.querySelector('[data-photo-field="source"]').value.trim(),license:row.querySelector('[data-photo-field="license"]').value.trim(),licenseUrl:row.querySelector('[data-photo-field="licenseUrl"]').value.trim()}));}
function renderGallery(){$('gallery-editor').innerHTML=gallery.map((p,i)=>`<div class="gallery-editor-row"><img src="${esc(p.url)}" alt="Extra car photo ${i+1}"><div class="field-grid">${[['url','Image URL'],['credit','Creator (if required)'],['source','Source page'],['license','Licence'],['licenseUrl','Licence URL']].map(([key,label])=>`<label class="field"><span>${label}</span><input data-photo-field="${key}" value="${esc(p[key]||'')}" maxlength="${['credit'].includes(key)?200:key==='license'?60:2000}"></label>`).join('')}</div><button type="button" class="secondary" data-remove-photo="${i}">Remove photo</button></div>`).join('');$('gallery-editor').onclick=event=>{const button=event.target.closest('[data-remove-photo]');if(!button||uploading)return;gallery=readGallery();gallery.splice(Number(button.dataset.removePhoto),1);dirty=true;renderGallery();};}
async function uploadGallery(){const files=[...$('gallery-upload').files];if(!files.length)return;gallery=readGallery();if(files.length+gallery.length>7){$('form-error').textContent='Add up to seven extra photos per car.';return;}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)){$('form-error').textContent='Each photo must be JPG, PNG or WebP, up to 8 MB.';return;}uploading=true;dirty=true;$('save-button').disabled=true;$('gallery-upload').disabled=true;$('form-error').textContent='';try{for(const file of files){$('gallery-status').textContent='Uploading '+file.name+'…';const result=await api('/api/admin/photos',{method:'POST',headers:{'Content-Type':file.type},body:file});gallery.push({url:result.url,credit:'',source:'',license:'',licenseUrl:''});}renderGallery();$('gallery-status').textContent='Photos uploaded. Save the car to update its slideshow.';}catch(error){renderGallery();$('form-error').textContent=error.message;$('gallery-status').textContent='Some photos could not be uploaded. Review the gallery before saving.';}finally{uploading=false;$('save-button').disabled=false;$('gallery-upload').disabled=false;$('gallery-upload').value='';}}

async function refreshDashboard(){const button=$('refresh');if(button.disabled)return;button.disabled=true;button.textContent='Refreshing…';button.setAttribute('aria-busy','true');try{const ok=window.customerAdmin?.active?await window.customerAdmin.load():await load();await window.customerAdmin?.refreshNotices();if(ok)toast('Updated just now. You’re viewing the latest saved data.');}catch(e){$('admin-error').textContent=e.message;}finally{button.disabled=false;button.textContent='Refresh';button.removeAttribute('aria-busy');}}
